import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';

const Register = () => {
  const navigate = useNavigate();
  const [institutions, setInstitutions] = useState([]);
  const [selectedInst, setSelectedInst] = useState(null);

  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    password: '',
    phone: '',
    role: 'student',
    institutionId: '',
    department: '',
    course: '',
    yearOrSemester: '',
    enrollmentNumber: '',
    aadhaarNumber: '',
    dlNumber: '',
    idCardUrl: '',
    dlUrl: '',
    selfieUrl: ''
  });

  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Load institutions list
  useEffect(() => {
    axios.get('http://localhost:5000/api/auth/institutions')
      .then(res => {
        setInstitutions(res.data);
        if (res.data.length > 0) {
          // Set initial default selection
          setSelectedInst(res.data[0]);
          setFormData(prev => ({ ...prev, institutionId: res.data[0].code }));
        }
      })
      .catch(err => {
        console.error("Failed to load institutions list", err);
      });
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));

    if (name === 'institutionId') {
      const selected = institutions.find(i => i.code === value);
      setSelectedInst(selected || null);
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    // Pre-validate email domain client-side
    if (selectedInst) {
      const emailDomain = formData.email.split('@')[1];
      if (!emailDomain || emailDomain.toLowerCase() !== selectedInst.emailDomain.toLowerCase()) {
        setError(`Please register using your official university email ending in @${selectedInst.emailDomain}`);
        setLoading(false);
        return;
      }
    }

    try {
      const res = await axios.post('http://localhost:5000/api/auth/register', formData);
      localStorage.setItem('vrx_token', res.data.token);
      localStorage.setItem('vrx_user', JSON.stringify(res.data.user));
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.error || 'Registration failed. Check inputs.');
    }
    setLoading(false);
  };

  return (
    <div style={{ minHeight: '120vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'linear-gradient(135deg, #F8FAFC 0%, #E2E8F0 100%)', padding: '40px 15px' }}>
      <div className="bg-white p-5 rounded-4 shadow" style={{ width: '100%', maxWidth: '650px' }}>
        <div className="text-center mb-4">
          <Link to="/" style={{ textDecoration: 'none', color: 'var(--dark)' }}>
            {selectedInst && selectedInst.branding?.logoUrl ? (
              <img src={selectedInst.branding.logoUrl} alt="Institution Crest" className="mb-2" style={{ height: '70px', objectFit: 'contain' }} />
            ) : (
              <img src="/assets/igntu_logo.png" alt="IGNTU Emblem" className="mb-2" style={{ height: '70px' }} />
            )}
            <h3 className="fw-bold m-0" style={{ color: 'var(--primary, #15803D)' }}>VehicleRentx</h3>
            <p className="text-muted small">Campus Mobility Portal</p>
          </Link>
          <h5 className="mt-2 text-muted">Create Verified Profile</h5>
          <p className="text-muted small">Closed campus ecosystem. Enrolling includes ₹500 free ride credits!</p>
        </div>

        {error && <div className="alert alert-danger py-2 small">{error}</div>}

        <form onSubmit={handleRegister}>
          <div className="row">
            {/* Step 1: Institutional Core Info */}
            <div className="col-md-6 mb-3">
              <label className="form-label fw-bold small text-muted">CHOOSE CAMPUS / TENANT</label>
              <select name="institutionId" className="form-select p-3 bg-light border-0 rounded-3" value={formData.institutionId} onChange={handleChange} required>
                {institutions.map(inst => (
                  <option key={inst.code} value={inst.code}>{inst.name} ({inst.code})</option>
                ))}
              </select>
            </div>

            <div className="col-md-6 mb-3">
              <label className="form-label fw-bold small text-muted">REGISTRATION ROLE</label>
              <select name="role" className="form-select p-3 bg-light border-0 rounded-3" value={formData.role} onChange={handleChange} required>
                <option value="student">Student</option>
                <option value="faculty">Faculty Member</option>
                <option value="research_scholar">Research Scholar</option>
                <option value="non_teaching">Non-Teaching Staff</option>
                <option value="vehicle_owner">Vehicle Owner / Partner</option>
              </select>
            </div>

            <div className="col-md-6 mb-3">
              <label className="form-label fw-bold small text-muted">FULL NAME (As in ID)</label>
              <input type="text" name="fullName" required className="form-control p-3 bg-light border-0 rounded-3" placeholder="Navin Divan" value={formData.fullName} onChange={handleChange} />
            </div>

            <div className="col-md-6 mb-3">
              <label className="form-label fw-bold small text-muted">MOBILE NUMBER</label>
              <input type="tel" name="phone" required className="form-control p-3 bg-light border-0 rounded-3" placeholder="e.g. 9876543210" value={formData.phone} onChange={handleChange} />
            </div>

            <div className="col-12 mb-3">
              <label className="form-label fw-bold small text-muted">
                OFFICIAL UNIVERSITY EMAIL ADDRESS 
                {selectedInst && <span className="text-primary ms-1">(Must end with @{selectedInst.emailDomain})</span>}
              </label>
              <input type="email" name="email" required className="form-control p-3 bg-light border-0 rounded-3" placeholder={selectedInst ? `yourname@${selectedInst.emailDomain}` : "name@igntu.ac.in"} value={formData.email} onChange={handleChange} />
            </div>

            <div className="col-12 mb-3">
              <label className="form-label fw-bold small text-muted">ACCOUNT PASSWORD</label>
              <input type="password" name="password" required className="form-control p-3 bg-light border-0 rounded-3" placeholder="Create a strong password" value={formData.password} onChange={handleChange} />
            </div>

            {/* Step 2: Academic Details (Visible if student/faculty) */}
            {['student', 'faculty', 'research_scholar', 'non_teaching'].includes(formData.role) && (
              <>
                <hr className="my-3 text-muted" />
                <h6 className="fw-bold mb-3 text-secondary">Academic Credentials</h6>

                <div className="col-md-6 mb-3">
                  <label className="form-label fw-bold small text-muted">DEPARTMENT / SCHOOl</label>
                  <input type="text" name="department" className="form-control p-3 bg-light border-0 rounded-3" placeholder="Computer Science" value={formData.department} onChange={handleChange} required />
                </div>

                <div className="col-md-6 mb-3">
                  <label className="form-label fw-bold small text-muted">COURSE / DESIGNATION</label>
                  <input type="text" name="course" className="form-control p-3 bg-light border-0 rounded-3" placeholder="e.g. MCA / Professor" value={formData.course} onChange={handleChange} required />
                </div>

                <div className="col-md-6 mb-3">
                  <label className="form-label fw-bold small text-muted">YEAR / SEMESTER</label>
                  <input type="text" name="yearOrSemester" className="form-control p-3 bg-light border-0 rounded-3" placeholder="e.g. Semester III" value={formData.yearOrSemester} onChange={handleChange} required />
                </div>

                <div className="col-md-6 mb-3">
                  <label className="form-label fw-bold small text-muted">ENROLLMENT / EMPLOYEE NO.</label>
                  <input type="text" name="enrollmentNumber" className="form-control p-3 bg-light border-0 rounded-3" placeholder="e.g. IGNTU-2026-MCA10" value={formData.enrollmentNumber} onChange={handleChange} required />
                </div>
              </>
            )}

            {/* Step 3: Identity Verification (KYC) */}
            <hr className="my-3 text-muted" />
            <h6 className="fw-bold mb-3 text-secondary">SaaS Tenant Identity (KYC Details)</h6>

            <div className="col-md-6 mb-3">
              <label className="form-label fw-bold small text-muted">AADHAAR CARD NUMBER</label>
              <input type="text" name="aadhaarNumber" className="form-control p-3 bg-light border-0 rounded-3" placeholder="12-digit UID" value={formData.aadhaarNumber} onChange={handleChange} />
            </div>

            <div className="col-md-6 mb-3">
              <label className="form-label fw-bold small text-muted">DRIVING LICENSE NUMBER</label>
              <input type="text" name="dlNumber" className="form-control p-3 bg-light border-0 rounded-3" placeholder="DL-XXXXXXXXXXXXXXXX" value={formData.dlNumber} onChange={handleChange} />
            </div>

            <div className="col-md-4 mb-3">
              <label className="form-label fw-bold small text-muted text-truncate">STUDENT/EMP ID URL</label>
              <input type="text" name="idCardUrl" className="form-control p-3 bg-light border-0 rounded-3 small" placeholder="Or leave blank for mock" value={formData.idCardUrl} onChange={handleChange} />
            </div>

            <div className="col-md-4 mb-3">
              <label className="form-label fw-bold small text-muted text-truncate">DL DOCUMENT URL</label>
              <input type="text" name="dlUrl" className="form-control p-3 bg-light border-0 rounded-3 small" placeholder="Or leave blank for mock" value={formData.dlUrl} onChange={handleChange} />
            </div>

            <div className="col-md-4 mb-3">
              <label className="form-label fw-bold small text-muted text-truncate">SELFIE/FACE LINK</label>
              <input type="text" name="selfieUrl" className="form-control p-3 bg-light border-0 rounded-3 small" placeholder="Or leave blank for mock" value={formData.selfieUrl} onChange={handleChange} />
            </div>
          </div>

          <button type="submit" className="btn btn-primary-custom w-100 py-3 mt-4" disabled={loading} style={{ background: selectedInst?.branding?.primaryColor || '#15803D', borderColor: selectedInst?.branding?.primaryColor || '#15803D' }}>
            {loading ? <><i className="fa-solid fa-spinner fa-spin me-2"></i>Verifying & Registering...</> : 'Complete SaaS Onboarding'}
          </button>
        </form>

        <div className="text-center mt-4 text-muted">
          Already have an account? <Link to="/login" className="fw-bold text-primary" style={{ color: selectedInst?.branding?.secondaryColor || '#1D4ED8' }}>Log in</Link>
        </div>
      </div>
    </div>
  );
};

export default Register;
